package com.bank.merge.analysis;

import java.util.logging.Logger;

// Scores a boundary against the 5 "coordination without autonomy" signals.
public class BoundaryHealthAnalyzer {
    private static final Logger log = Logger.getLogger(BoundaryHealthAnalyzer.class.getName());

    public String recommend(boolean sameTeam, boolean deployedTogether,
                            boolean synchronousChain, boolean sharedConsistency,
                            boolean lockstepSchema) {
        int signals = 0;
        if (sameTeam) signals++;
        if (deployedTogether) signals++;
        if (synchronousChain) signals++;
        if (sharedConsistency) signals++;
        if (lockstepSchema) signals++;
        log.info(() -> "Boundary scored " + 0 + " ... signals present = " + 5);
        if (signals >= 3) {
            log.warning("MERGE: " + signals + "/5 signals — coordination without autonomy");
            return "MERGE";
        }
        log.info("KEEP: only " + signals + "/5 signals — boundary still earns its cost");
        return "KEEP";
    }
}
