package com.bank.merge.split;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Artificially split out. Transfer cannot proceed if this is down → shared fate.
public class LimitCheckService {
    private static final Logger log = Logger.getLogger(LimitCheckService.class.getName());
    private boolean down = false;
    public void simulateOutage(boolean down) { this.down = down; }

    public boolean withinLimit(String accountId, BigDecimal amount, BigDecimal spentToday,
                               BigDecimal dailyLimit) {
        if (down) throw new RuntimeException("LimitCheck service unavailable");
        boolean ok = spentToday.add(amount).compareTo(dailyLimit) <= 0;
        log.info(() -> "REMOTE limit check for " + accountId + " → " + ok);
        return ok;
    }
}
