package com.bank.merge.split;

import java.math.BigDecimal;
import java.util.logging.Level;
import java.util.logging.Logger;

// Every transfer makes a BLOCKING remote call to LimitCheck (synchronous chain).
public class SplitTransferService {
    private static final Logger log = Logger.getLogger(SplitTransferService.class.getName());
    private final LimitCheckService limitCheck;
    public SplitTransferService(LimitCheckService limitCheck) { this.limitCheck = limitCheck; }

    public String transfer(String accountId, BigDecimal amount) {
        try {
            boolean ok = limitCheck.withinLimit(accountId, amount,
                    new BigDecimal("0"), new BigDecimal("200000"));
            if (!ok) return "REJECTED_LIMIT";
            log.info(() -> "SPLIT transfer " + amount + " from " + accountId);
            return "COMPLETED";
        } catch (RuntimeException ex) {
            log.log(Level.SEVERE, "Transfer blocked because LimitCheck is down", ex);
            return "BLOCKED_DEPENDENCY_DOWN";   // shared availability fate
        }
    }
}
