package com.bank.merge.merged;

import java.math.BigDecimal;
import java.util.logging.Logger;

// MERGED: limit check is now an in-process method call. One local transaction,
// no network, no shared-fate dependency.
public class MergedTransferService {
    private static final Logger log = Logger.getLogger(MergedTransferService.class.getName());

    public String transfer(String accountId, BigDecimal amount,
                           BigDecimal spentToday, BigDecimal dailyLimit) {
        if (!withinLimit(amount, spentToday, dailyLimit)) return "REJECTED_LIMIT";
        log.info(() -> "MERGED transfer " + amount + " from " + accountId + " (one local TX)");
        return "COMPLETED";
    }
    // in-process, no network, no circuit breaker needed
    private boolean withinLimit(BigDecimal amount, BigDecimal spentToday, BigDecimal dailyLimit) {
        return spentToday.add(amount).compareTo(dailyLimit) <= 0;
    }
}
