package com.bank.merge;

import com.bank.merge.analysis.BoundaryHealthAnalyzer;
import com.bank.merge.merged.MergedTransferService;
import com.bank.merge.split.LimitCheckService;
import com.bank.merge.split.SplitTransferService;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class MergeServicesDemo {
    private static final Logger log = Logger.getLogger(MergeServicesDemo.class.getName());

    public static void main(String[] args) {
        BigDecimal rentAmount = new BigDecimal("50000");

        log.info("=== 1. Analyze the boundary ===");
        String verdict = new BoundaryHealthAnalyzer()
            .recommend(true, true, true, true, true);
        log.info("Recommendation: " + verdict);

        log.info("=== 2. Split version is fragile when LimitCheck is down ===");
        LimitCheckService limitCheck = new LimitCheckService();
        SplitTransferService split = new SplitTransferService(limitCheck);
        log.info("Healthy: " + split.transfer("SAV2001", rentAmount));
        limitCheck.simulateOutage(true);
        log.info("LimitCheck down: " + split.transfer("SAV2001", rentAmount));

        log.info("=== 3. Merged version is one resilient unit ===");
        MergedTransferService merged = new MergedTransferService();
        log.info("Merged: " + merged.transfer("SAV2001", rentAmount,
                new BigDecimal("0"), new BigDecimal("200000")));
    }
}
